import {
  catchError
} from "./packager-tool-79gws1zn.js";

// ../flow-tool/src/services/flow-eval-file-store.ts
async function ensureDirectory(fs, path) {
  if (await fs.exists(path)) {
    return;
  }
  const parent = fs.path.dirname(path);
  if (parent && parent !== path && !await fs.exists(parent)) {
    await ensureDirectory(fs, parent);
  }
  const [error] = await catchError(fs.mkdir(path));
  if (error && !await fs.exists(path)) {
    throw error;
  }
}

class FlowEvalFileStore {
  fs;
  constructor(fs) {
    this.fs = fs;
  }
  async readJsonFiles(dir) {
    const [readDirError, files] = await catchError(this.fs.readdir(dir));
    if (readDirError) {
      return [];
    }
    const items = [];
    for (const file of files) {
      if (!file.endsWith(".json")) {
        continue;
      }
      const filePath = this.fs.path.join(dir, file);
      const [readError, raw] = await catchError(this.fs.readFile(filePath, "utf-8"));
      if (readError) {
        throw new Error(`Failed to read JSON file "${filePath}": ${readError.message}`);
      }
      if (raw === null) {
        continue;
      }
      const [parseError, data] = catchError(() => JSON.parse(String(raw)));
      if (parseError) {
        throw new Error(`Invalid JSON in "${filePath}": ${parseError.message}`);
      }
      data.fileName = file;
      items.push(data);
    }
    return items;
  }
  async writeJsonFile(path, value) {
    await ensureDirectory(this.fs, this.fs.path.dirname(path));
    await this.fs.writeFile(path, `${JSON.stringify(value, null, 2)}
`);
  }
  async remove(path) {
    await this.fs.rm(path);
  }
}

export { ensureDirectory, FlowEvalFileStore };

